	}
	sort.Strings(languages)
	semanticLanguages := sortedSetKeys(semanticLanguageSet)
	inventoryOnlyLanguages := sortedSetKeys(inventoryOnlyLanguageSet)

	return CapabilityReport{
		SchemaVersion:                   SchemaVersion,
